 * - notice: 띄운 알림의 제목·본문
 */
function PurchaseScreen({
  loggedIn,
  buyProductId,
  notice,
}: {
  loggedIn: boolean;
  buyProductId?: string;
  notice: { title: string; message: string };
}) {
  return (
